PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, username TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'admin', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS products (id INTEGER PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', category TEXT NOT NULL CHECK(category IN ('digital','physical')), price_cents INTEGER NOT NULL CHECK(price_cents >= 0), currency TEXT NOT NULL DEFAULT 'eur', image_path TEXT, digital_file_path TEXT, stock INTEGER, published INTEGER NOT NULL DEFAULT 0, release_date TEXT, translations_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS posts (id INTEGER PRIMARY KEY, caption TEXT NOT NULL DEFAULT '', media_path TEXT, media_type TEXT, status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','scheduled','published','failed')), scheduled_at TEXT, platforms_json TEXT NOT NULL DEFAULT '[]', platform_results_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS orders (id INTEGER PRIMARY KEY, email TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','paid','refunded','cancelled')), provider TEXT NOT NULL, provider_session_id TEXT UNIQUE, total_cents INTEGER NOT NULL, currency TEXT NOT NULL DEFAULT 'eur', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS order_items (id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES orders(id), product_id INTEGER NOT NULL REFERENCES products(id), quantity INTEGER NOT NULL CHECK(quantity > 0), unit_price_cents INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS download_tokens (id INTEGER PRIMARY KEY, order_item_id INTEGER NOT NULL REFERENCES order_items(id), token_hash TEXT UNIQUE NOT NULL, expires_at TEXT NOT NULL, max_downloads INTEGER NOT NULL DEFAULT 5, downloads INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS newsletter_subscribers (id INTEGER PRIMARY KEY, email TEXT UNIQUE NOT NULL, locale TEXT NOT NULL DEFAULT 'it', confirmed_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS analytics_events (id INTEGER PRIMARY KEY, event TEXT NOT NULL, product_id INTEGER, session_hash TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
